info.description:
@-moz-document domain("youtube.com") {
    /* Меняет цвет ника модератора в обычном чате */
    yt-live-chat-text-message-renderer[author-type="moderator"] #author-name {
        color: #FF0000 !important;
    }
    
    /* Меняет цвет значка гаечного ключа (опционально) */
    yt-live-chat-text-message-renderer[author-type="moderator"] yt-live-chat-author-badge-renderer {
        --yt-live-chat-moderator-color: #FF0000 !important;
    }
}

